661	                              LV_PART_INDICATOR);
662	    lv_obj_set_style_radius(slider, DM(3), LV_PART_INDICATOR);
663	    lv_obj_set_style_radius(slider, DM(3), LV_PART_KNOB);
664	    lv_obj_set_style_bg_color(slider, lv_color_hex(0xFFFFFF), LV_PART_KNOB);
