/* Brightness slider → 屏幕背光（PWM ch4 @40KHz，BOE 面板）+ WS2812 LED
 * 2026-08-08 修复：此前只调 WS2812 LED 亮度，屏幕背光不变 → "不能用"；
 * 现同步调屏幕背光 PWM ch4 duty（period=25000ns，polarity 与 BOE config
 * lcd_pwm_pol=0 一致），0-100 线性映射 duty_ns。 */
static void settings_brightness_cb(lv_event_t *e)
{
    lv_obj_t *slider = lv_event_get_target(e);
    int32_t v = lv_slider_get_value(slider);
    lv_obj_t *val_lbl = (lv_obj_t *)lv_obj_get_user_data(slider);
    if (val_lbl) {
        char buf[8];
        snprintf(buf, sizeof(buf), "%d%%", (int)v);
        lv_label_set_text(val_lbl, buf);
    }
#ifdef CONFIG_LUNCHER_DM_APP
    {
        struct pwm_config pcfg;
        memset(&pcfg, 0, sizeof(pcfg));
        pcfg.period_ns  = 25000;                       /* 40KHz */
        pcfg.duty_ns    = (uint32_t)(25000u * v / 100); /* 0-100 → 0-25000ns */
        pcfg.polarity   = PWM_POLARITY_INVERSED;       /* 与 lcd_pwm_pol=0 一致 */
        hal_pwm_control(4, &pcfg);                     /* 屏幕背光 PWM ch4 */
    }
#endif
#ifdef CONFIG_LED_RGB_WS2812
    dm_led_set_brightness(v);   /* WS2812 LED，0-100 (board only) */
#endif
}

